<div class="flex flex-wrap gap-2 mb-4"><a class="btn btn-outline btn-sm" href="<?= e(url('/admin/products')) ?>">← Products</a><a class="btn btn-primary btn-sm" href="<?= e(url('/admin/products/' . $p['id'] . '/edit')) ?>">Edit</a><?php if ($p['status'] === 'active'): ?><a class="btn btn-soft btn-sm" target="_blank" href="<?= e(url('/product-details.php?id=' . $p['id'])) ?>">View on website</a><?php endif; ?></div>
<div class="grid lg:grid-cols-3 gap-4"><div class="card p-5"><div class="grid grid-cols-2 gap-2"><?php foreach ($images as $im): ?><img src="<?= e(upload_url($im['path'])) ?>" class="rounded-lg aspect-square object-cover w-full <?= $im['is_primary'] ? 'ring-2 ring-primary' : '' ?>" alt=""><?php endforeach; if (!$images): ?><p class="muted text-sm col-span-2">No images.</p><?php endif; ?></div></div>
<div class="card p-5 lg:col-span-2"><h2 class="text-xl font-bold"><?= e($p['name']) ?></h2><p class="muted text-sm font-mono"><?= e($p['sku']) ?> · ID <?= (int)$p['id'] ?> · <?= e($p['category_name']) ?></p>
<dl class="grid sm:grid-cols-4 gap-3 mt-4 text-sm"><?php foreach ([['Original', money($p['original_price'])], ['Selling', money($p['selling_price'])], ['Discount', $p['discount_percent'] . '%'], ['Stock', (int)$p['stock']], ['Low-stock at', (int)$p['low_stock_threshold']], ['Units sold', $sold], ['Status', $p['status']], ['Featured/Popular', ($p['is_featured'] ? 'Yes' : 'No') . ' / ' . ($p['is_popular'] ? 'Yes' : 'No')]] as [$k, $v]): ?><div class="rounded-xl bg-gray-50 p-3"><dt class="text-xs muted"><?= e($k) ?></dt><dd class="font-bold"><?= e($v) ?></dd></div><?php endforeach; ?></dl>
<h3 class="font-bold mt-5">Description</h3><p class="text-sm muted whitespace-pre-line"><?= e($p['description'] ?: '—') ?></p><h3 class="font-bold mt-4">Safety notes</h3><p class="text-sm muted whitespace-pre-line"><?= e($p['safety_notes'] ?: '—') ?></p><h3 class="font-bold mt-4">Voice aliases</h3><p class="text-sm muted"><?= e($p['aliases'] ?: '—') ?></p></div></div>
